arduino.globals:
#include <IRremote.h>

const int RECV_PIN_${COMP_SUFFIX} = ${OUT};
IRrecv irrecv_${COMP_SUFFIX}(RECV_PIN_${COMP_SUFFIX});
decode_results results_${COMP_SUFFIX};

arduino.loop:
if (irrecv_${COMP_SUFFIX}.decode(&results_${COMP_SUFFIX})) {
  Serial.print("IR Code: 0x");
  Serial.println(results_${COMP_SUFFIX}.value, HEX);
  irrecv_${COMP_SUFFIX}.resume();
}
delay(100);
